const HTML="<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>TEREM Ornament v2 — Proof</title>\n<style>\n:root{color-scheme:dark;--bg:#0c0b0a;--card:#151311;--line:#302b26;--text:#f3eee7;--muted:#9f968b;--gold:#d8b86b;--ok:#87c996}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 Inter,Arial,sans-serif}\nmain{max-width:1540px;margin:auto;padding:24px}.top{display:flex;gap:20px;align-items:end;justify-content:space-between;margin-bottom:20px}\nh1{font-size:clamp(24px,3vw,42px);margin:0 0 5px;letter-spacing:-.035em}.sub{color:var(--muted);max-width:850px}\n.badges{display:flex;gap:8px;flex-wrap:wrap}.badge{border:1px solid var(--line);padding:7px 10px;border-radius:999px;color:var(--muted);white-space:nowrap}.badge.ok{color:var(--ok)}\n.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;overflow:hidden}\n.head{padding:14px 15px 10px}.k{font-size:11px;color:var(--gold);text-transform:uppercase;letter-spacing:.12em}.title{font-size:18px;font-weight:650;margin-top:3px}\n.visual{aspect-ratio:600/536;display:grid;place-items:center;background:#211e1a;border-top:1px solid var(--line);border-bottom:1px solid var(--line);cursor:zoom-in}\n.visual.reference{background:#f6f2ea}.visual img{width:100%;height:100%;object-fit:contain;display:block}.meta{padding:12px 15px 15px;color:var(--muted);min-height:102px}.meta b{color:var(--text);font-weight:600}\n.proof{margin-top:14px;display:grid;grid-template-columns:1.2fr .8fr;gap:14px}.panel{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:16px}\n.panel h2{font-size:17px;margin:0 0 10px}.equation{font:15px ui-monospace,SFMono-Regular,Consolas,monospace;color:#ddd;white-space:normal}.facts{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:12px}.fact{padding:10px;border:1px solid var(--line);border-radius:10px}.fact strong{display:block;font-size:19px}.fact span{color:var(--muted);font-size:12px}\ntextarea{width:100%;min-height:92px;background:#0e0d0c;color:var(--text);border:1px solid var(--line);border-radius:10px;padding:10px;resize:vertical}\nbutton{margin-top:9px;border:0;border-radius:10px;padding:11px 14px;font-weight:650;cursor:pointer;background:var(--text);color:#111}button:disabled{opacity:.45;cursor:wait}\n#aiResult{margin-top:12px}#aiResult img{width:100%;border-radius:12px;border:1px solid var(--line)}#cost{color:var(--gold);margin-top:6px}\ndialog{padding:0;border:1px solid #51483f;border-radius:16px;background:#0a0908;max-width:96vw;max-height:96vh}dialog::backdrop{background:#000c}dialog img{display:block;max-width:94vw;max-height:90vh}dialog button{position:absolute;right:8px;top:8px;margin:0}\n@media(max-width:980px){.grid{grid-template-columns:1fr}.proof{grid-template-columns:1fr}.facts{grid-template-columns:repeat(2,1fr)}.top{align-items:start;flex-direction:column}}\n</style></head>\n<body><main>\n<div class=\"top\"><div><h1>TRM-0108 · проверка математической модели</h1><div class=\"sub\">Один референс, две независимые модели: локальная геометрия формы и геометрия всего рисунка. Третья панель не повторяет исходные абсолютные координаты.</div></div>\n<div class=\"badges\"><span class=\"badge ok\">Two-layer gate: PASS</span><span class=\"badge\">C12 radial rosette</span><span class=\"badge\">DERIVED / UNKNOWN</span></div></div>\n<section class=\"grid\">\n<article class=\"card\"><div class=\"head\"><div class=\"k\">01 · Reference</div><div class=\"title\">Исходный референс</div></div><div class=\"visual reference\" data-src=\"/reference.svg\"><img src=\"/reference.svg\" alt=\"TRM-0108 reconstructed vector reference\"></div><div class=\"meta\"><b>RECONSTRUCTED vector master.</b><br>Это исходная геометрия, из которой извлечены Form Logic и Pattern Logic. Не выдаётся за подтверждённый исторический оригинал.</div></article>\n<article class=\"card\"><div class=\"head\"><div class=\"k\">02 · Reconstruction</div><div class=\"title\">Математическая реконструкция</div></div><div class=\"visual\" data-src=\"/reconstruction.svg\"><img src=\"/reconstruction.svg\" alt=\"Mathematical reconstruction\"></div><div class=\"meta\"><b>28 / 28 Form Models.</b><br>Pattern Model: radial_rosette · C12 · confidence 0.816613. Здесь проверяется, что обе математические модели снова собирают структуру референса.</div></article>\n<article class=\"card\"><div class=\"head\"><div class=\"k\">03 · Variation</div><div class=\"title\">Новый орнамент по тем же законам</div></div><div class=\"visual\" data-src=\"/variation.svg\"><img src=\"/variation.svg\" alt=\"Independent mathematical variation\"></div><div class=\"meta\"><b>Seed 10842 · 48 instances.</b><br>4 Form Models из наблюдаемой последовательности × 12 секторов. Только similarity transforms; исходные абсолютные координаты не используются.</div></article>\n</section>\n<section class=\"proof\">\n<div class=\"panel\"><h2>Что именно доказано</h2><div class=\"equation\">REFERENCE → FORM LOGIC ⊕ PATTERN LOGIC → RECONSTRUCTION → NEW VARIATION</div>\n<div class=\"facts\"><div class=\"fact\"><strong>2 490</strong><span>Form Models корпуса</span></div><div class=\"fact\"><strong>150</strong><span>Pattern Models</span></div><div class=\"fact\"><strong>12</strong><span>порядок вращения TRM-0108</span></div><div class=\"fact\"><strong>0</strong><span>повторно используемых абсолютных координат в variation</span></div></div>\n<p class=\"sub\">Инвариант: Pattern Logic может переносить, вращать и масштабировать результат Form Logic, но не имеет права переписывать локальные параметры формы.</p></div>\n<div class=\"panel\"><h2>Опциональная AI-визуализация</h2><div class=\"sub\">AI получает уже готовую математическую вариацию только как визуальный reference. Геометрию орнамента он не определяет.</div>\n<textarea id=\"prompt\">Сохрани точную структуру и взаимное расположение линий математического орнамента. Визуализируй его как премиальную историческую декоративную роспись: глубокий красный фон, тёплое золото, минеральные зелёные и синие акценты, ручная живописная фактура. Не добавляй новые ветви, листья или розетки.</textarea>\n<button id=\"render\">AI-визуализация через OpenRouter</button><div id=\"cost\"></div><div id=\"aiResult\"></div></div>\n</section>\n</main>\n<dialog id=\"zoom\"><button onclick=\"zoom.close()\">Закрыть</button><img id=\"zoomImg\"></dialog>\n<script>\nconst zoom=document.getElementById('zoom'),zoomImg=document.getElementById('zoomImg');\ndocument.querySelectorAll('.visual').forEach(v=>v.onclick=()=>{zoomImg.src=v.dataset.src;zoom.showModal()});\nzoom.onclick=e=>{if(e.target===zoom)zoom.close()};\nasync function rasterizeSvg(url){\n const svg=await (await fetch(url)).text(); const blob=new Blob([svg],{type:'image/svg+xml'}); const u=URL.createObjectURL(blob);\n try{const img=new Image(); await new Promise((ok,fail)=>{img.onload=ok;img.onerror=fail;img.src=u});\n const c=document.createElement('canvas');c.width=1200;c.height=1072;const x=c.getContext('2d');x.fillStyle='#15110e';x.fillRect(0,0,c.width,c.height);x.drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/png')}finally{URL.revokeObjectURL(u)}\n}\ndocument.getElementById('render').onclick=async()=>{\n const b=document.getElementById('render'),cost=document.getElementById('cost'),out=document.getElementById('aiResult');b.disabled=true;cost.textContent='Генерация…';out.innerHTML='';\n try{const image_data_url=await rasterizeSvg('/variation.svg');const r=await fetch('/api/visualize',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt:document.getElementById('prompt').value,image_data_url})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||('HTTP '+r.status));out.innerHTML='<img alt=\"AI visualization\" src=\"'+d.image_data_url+'\">';cost.textContent='Модель: '+d.model+' · стоимость этой генерации: $'+Number(d.cost||0).toFixed(6)}catch(e){cost.textContent='Ошибка: '+e.message}finally{b.disabled=false}\n};\n</script></body></html>";
